<?php require_once '../includes/functions.php';require_user();$uid=user()['id'];$a=$pdo->prepare('SELECT COUNT(*) FROM favorites WHERE user_id=?');$a->execute([$uid]);$fav=$a->fetchColumn();$a=$pdo->prepare('SELECT COUNT(*) FROM trips WHERE user_id=?');$a->execute([$uid]);$tripcount=$a->fetchColumn();$a=$pdo->prepare('SELECT COUNT(*) FROM reviews WHERE user_id=?');$a->execute([$uid]);$reviewcount=$a->fetchColumn();$a=$pdo->prepare('SELECT p.* FROM favorites f JOIN places p ON p.id=f.place_id WHERE f.user_id=? ORDER BY f.created_at DESC LIMIT 3');$a->execute([$uid]);$favorites=$a->fetchAll();$a=$pdo->prepare('SELECT t.*,p.name,p.cover_image FROM trips t JOIN places p ON p.id=t.place_id WHERE t.user_id=? ORDER BY t.trip_date LIMIT 3');$a->execute([$uid]);$trips=$a->fetchAll();$page_title='My Dashboard';require '../includes/header.php';?><section class="dashboard-layout"><aside class="sidebar"><div class="profile-mini"><div class="avatar">☺</div><b>Welcome, <?=e(user()['name'])?></b><small><?=e(user()['email'])?></small></div><a class="selected" href="dashboard.php">▦ Dashboard</a><a href="favorites.php">♡ My Favorites</a><a href="trips.php">▣ My Trip Plan</a><a href="reviews.php">★ Reviews</a><a href="profile.php">⚙ Profile Settings</a><a href="<?=url('auth/logout.php')?>">↪ Logout</a></aside><div class="dashboard-main"><h1>Dashboard</h1><div class="stats-grid"><div class="stat-card"><span>♡</span><b><?=$fav?></b><small>Favorites</small></div><div class="stat-card"><span>▣</span><b><?=$tripcount?></b><small>Trip Plans</small></div><div class="stat-card"><span>★</span><b><?=$reviewcount?></b><small>Reviews</small></div></div><div class="section-heading"><div><h2>My Favorites</h2><p>Your saved places</p></div><a href="favorites.php">View all →</a></div><div class="mini-grid"><?php foreach($favorites as $p):?><a class="place-card" href="<?=url('place.php?slug='.urlencode($p['slug']))?>"><img src="<?=e(image_url($p['cover_image']))?>" alt=""><div class="place-info"><b><?=e($p['name'])?></b><small><?=e($p['district'])?></small></div></a><?php endforeach;?></div><div class="section-heading"><div><h2>Upcoming Trips</h2><p>Your planned journeys</p></div><a href="trips.php">View all →</a></div><?php foreach($trips as $t):?><div class="trip-row"><img src="<?=e(image_url($t['cover_image']))?>"><div><b><?=e($t['name'])?></b><small><?=e($t['trip_date'])?> · <?=$t['people']?> people · <?=money($t['budget'])?></small></div><span class="status-pill">Upcoming</span></div><?php endforeach;?></div></section><?php require '../includes/footer.php';?>
